<script>
 import {formatValue} from '$lib/energy';
 let {history=null,range='today'}=$props();let hover=$state(-1);
 let times=$derived([...new Set([...(history?.solar || []).map(p=>p.time),...(history?.consumption || []).map(p=>p.time)])].sort());
 let rows=$derived(times.map(time=>({time,solar:history?.solar?.find(p=>p.time===time)?.value??null,consumption:history?.consumption?.find(p=>p.time===time)?.value??null})));
 let max=$derived(Math.max(.1,...rows.flatMap(r=>[r.solar,r.consumption]).filter(v=>v!==null)));
 function label(time){return new Intl.DateTimeFormat('en-ZW',{timeZone:'Africa/Harare',...(range==='today'?{hour:'2-digit',hour12:false}:{month:'short',day:'numeric'})}).format(new Date(time));}
</script>
<div class="chart-legend"><span><i class="solar-key"></i>Solar generated</span><span><i class="usage-key"></i>Energy consumed</span><small>kWh / {range==='today'?'hour':'day'}</small></div>
{#if rows.length}<div class="energy-chart" role="group" aria-label="Solar generation and energy consumption by period"><div class="chart-y"><span>{formatValue(max,'',1)}</span><span>{formatValue(max/2,'',1)}</span><span>0</span></div><div class="chart-plot"><div class="chart-gridline top"></div><div class="chart-gridline mid"></div><div class="chart-gridline bottom"></div><div class="chart-bars">{#each rows as row,i}<button type="button" class="chart-column" onclick={()=>hover=i} onfocus={()=>hover=i} onblur={()=>hover=-1} onmouseenter={()=>hover=i} onmouseleave={()=>hover=-1} aria-label={`${label(row.time)}: solar ${formatValue(row.solar,'kWh')}, consumed ${formatValue(row.consumption,'kWh')}`}><span class="bar-pair"><i class="solar-bar" style:height={`${row.solar===null?0:Math.max(row.solar/max*100,0)}%`}></i><i class="usage-bar" style:height={`${row.consumption===null?0:Math.max(row.consumption/max*100,0)}%`}></i></span><span class="chart-x">{i%Math.max(1,Math.ceil(rows.length/7))===0?label(row.time):''}</span></button>{/each}</div></div></div><div class="chart-detail" aria-live="polite">{#if hover>=0 && rows[hover]}<strong>{label(rows[hover].time)}</strong><span>Generated {formatValue(rows[hover].solar,'kWh',2)}</span><span>Consumed {formatValue(rows[hover].consumption,'kWh',2)}</span>{:else}<span>Choose a column to inspect its readings. Gaps mean data is unavailable.</span>{/if}</div>{:else}<div class="chart-empty"><span>No energy history yet</span><p>Measured generation and consumption will appear here after the installation is connected and verified.</p></div>{/if}
